// Legacy GEO interface of mrdoob/slop-newyork (the engine's geodata module), now backed by the Helsinki inner city.
// Everything Manhattan-specific is empty; the mapped OSM city lives in GEO.helsinki (the irregular-city data path
// of the engine, see helsinki-geometry.js) and is generated by tools/build-helsinki-geodata.mjs.
import { HELSINKI_DATA } from './helsinki-geodata.js';

const [minX, minZ, maxX, maxZ] = HELSINKI_DATA.meta.bounds;

export const GEO = {
  version: 2,
  city: 'Helsinki',
  cityName: 'Helsinki',
  frame: { bearingDeg: 0, origin: 'Senaatintori', units: 'm', cutZ: minZ, strip: 20, sidewalk: 3 },
  manhattan: [minX, minZ, maxX, minZ, maxX, maxZ, minX, maxZ],
  upperManhattan: [],
  streets: [],
  avenues: [],
  broadway: [],
  piers: [],
  islands: {},
  boroughs: { newJersey: [], brooklyn: [], queens: [], bronx: [], statenIsland: [] },
  bridges: {},
  points: {},
  plazas: [],
  centralPark: { bounds: { minX, maxX, minZ, maxZ }, lawns: [], water: HELSINKI_DATA.water, drives: [] },
  parks: HELSINKI_DATA.parks.map((p) => ({ name: p.name, kind: p.kind, rings: [p.ring], holes: p.holes })),
  landmarks: HELSINKI_DATA.landmarks,
  roads: [],
  blocks: [],
  roadGraph: HELSINKI_DATA.roadGraph,
  helsinki: HELSINKI_DATA
};
